#!/usr/bin/env bash
#
# pfApp.sh — dev helper for the ProjectForge app (projectforge-app, React Native), the counterpart of projectforge-flutter/bin/pfApp.sh
# and bin/pfDev.sh.
#
# Works from any working directory. Node and npm are taken from the PATH; the native projects (ios/, android/) are
# generated by expo prebuild (not in git) and created on the first run.
#
set -euo pipefail

# App dir = parent of bin/, resolved from this script's own location.
APP="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ROOT="$(cd "$APP/.." && pwd)"

# The dev client by default (bundle id de.projectforge.mobileapp.dev, see app.config.ts): it doesn't replace the store
# app on a device. The release builds set production; eas (store builds, submit) the store app unless given.
APP_VARIANT_GIVEN="${APP_VARIANT:-}"
export APP_VARIANT="${APP_VARIANT:-development}"

usage() {
  cat <<'EOF'
pfApp.sh <command> [slot] [args…] — ProjectForge React Native app dev helper

Commands:
  run [slot] [--android] [--ipad] [--proxy] [args…]
                   expo run:ios with the server of the slot (:8080+slot) preset in the
                   login; warns if it doesn't answer. Builds the dev client if needed,
                   installs it and starts Metro (:19000+slot, not the 8081 of Metro's
                   default, which is the server of slot 1). Without -d/--device it boots an
                   iOS simulator (or reuses the running one). --android: expo run:android,
                   the server as 10.0.2.2 (how the Android emulator reaches the Mac); boots
                   the emulator if no Android device is attached (see emulator).
                   --ipad: the simulator is an iPad Pro 13-inch. --proxy: the server behind
                   the fake SSO proxy (see proxy), started alongside; iOS only. Args are
                   forwarded (e.g. pfApp.sh run 1 --device "iPhone 18 Pro")
  metro [slot] [--proxy] [--android]
                   Only Metro for an installed dev client (after a JS change no build is
                   needed), with the server of the slot preset. --android: boots the
                   emulator and opens the installed app in it
  emulator [slot] [avd]
                   Boot the Android emulator (the first AVD, or the named one) unless a
                   device is attached, and forward Metro's port of the slot to it (adb
                   reverse: the emulator doesn't reach the Mac's LAN address)
  proxy [slot] [args…]
                   The fake SSO proxy (tools/fake-sso-proxy.mjs) in front of the server of the
                   slot: http://localhost:18080+slot, its SSO login on http://127.0.0.1:18180+slot.
                   Args are forwarded (--ttl <s>, --sso-ttl <s>, --interactive, --guard-public).
                   The server needs projectforge.app.proxyCookies=authentik_proxy_* in its
                   projectforge.properties
  sim [name|ipad]  Boot an iOS simulator (default: the first available iPhone; ipad: the
                   first iPad Pro 13-inch) and open Simulator.app
  devices          The available iOS simulators and the Android devices (adb)
  check            Quality gates: tsc (app and projectforge-shared) → eslint → jest
  test [args…]     jest, args forwarded (e.g. test webNavigation)
  lint             eslint
  format           eslint --fix
  typecheck        tsc --noEmit
  prebuild [ios|android]
                   Generate the native projects anew (expo prebuild --clean), e.g. after a
                   change of app.json, a config plugin or a native module
  build-ios [--release]
                   Simulator build of the dev client (debug), installed on the booted
                   simulator; --release: a release build (store builds: eas, see README)
  build-android [--release]
                   Build of the dev client (debug) on the Android device/emulator, or release
  xcode            Open the iOS project in Xcode (signing, capabilities)
  clean            Remove the native projects, caches and node_modules, then install again
  deps             npm install + the versions expo expects (expo install --check)
  doctor           expo-doctor
  eas [args…]      eas-cli (npx eas-cli@latest) with EXPO_OWNER and EAS_PROJECT_ID of .env.local
                   (gitignored), e.g. eas build --platform ios --profile preview
  logs             The log of the app in the booted iOS simulator
  help             Show this help

Slots as in bin/pfDev.sh: a number 1–9 picks the server :8080+n (bin/pfDev.sh run n), none :8080.

Env:
  ANDROID_HOME     The Android SDK (default: ~/Library/Android/sdk)
  APP_VARIANT      development (default: the dev client de.projectforge.mobileapp.dev) or
                   production (the store app de.projectforge.mobileapp), see app.config.ts
EOF
}

SLOT=0
parse_slot() {
  if [[ "${1:-}" =~ ^[1-9]$ ]]; then
    SLOT="$1"
  fi
  SPRING_PORT=$((8080 + SLOT))
  METRO_PORT=$((19000 + SLOT))
  # Built into the dev client as its default Metro port: without it, a dev client that doesn't reach Metro falls back
  # to :8081, the ProjectForge server of slot 1, which then logs the requests for the bundle as suspicious.
  export RCT_METRO_PORT="$METRO_PORT"
  PROXY_PORT=$((18080 + SLOT))
  SSO_PORT=$((18180 + SLOT))
}

# Installs the npm dependencies if they are missing (postinstall applies the patches of patches/).
ensure_deps() {
  [[ -d "$APP/node_modules" ]] || (cd "$APP" && npm install)
}

# Shows the booted simulator: Simulator.app up to Xcode 26, DeviceHub.app since Xcode 27. A window that doesn't open
# is no reason to stop, the simulator runs anyway.
open_simulator_app() {
  local xcode
  xcode="$(xcode-select -p)/.."
  open "$xcode/Applications/DeviceHub.app" 2>/dev/null ||
    open "$xcode/Developer/Applications/Simulator.app" 2>/dev/null ||
    open -a Simulator 2>/dev/null ||
    echo "(No simulator window: open it in Xcode, Window → Devices.)"
}

# Boots the Android emulator (the AVD $1, default the first one) unless a device is attached, waits for its boot and
# forwards Metro's port to it: the emulator doesn't reach the Mac's LAN address that expo announces.
boot_emulator() {
  export ANDROID_HOME="${ANDROID_HOME:-$HOME/Library/Android/sdk}"
  export PATH="$ANDROID_HOME/platform-tools:$ANDROID_HOME/emulator:$PATH"
  command -v adb >/dev/null 2>&1 || { echo "adb not found (Android SDK: Android Studio's setup)" >&2; exit 1; }
  if ! adb devices | awk 'NR > 1 && $2 == "device" { found = 1 } END { exit !found }'; then
    local avd="${1:-$(emulator -list-avds 2>/dev/null | head -1)}"
    [[ -n "$avd" ]] || { echo "No Android emulator (AVD): create one in Android Studio, Device Manager." >&2; exit 1; }
    echo "Booting the Android emulator $avd (log: /tmp/pf-emulator.log)…"
    nohup emulator -avd "$avd" -gpu host >/tmp/pf-emulator.log 2>&1 &
    local waited=0
    until [[ "$(adb shell getprop sys.boot_completed 2>/dev/null | tr -d '\r')" == 1 ]]; do
      if ((waited >= 300)); then
        echo "The emulator didn't boot within 5 minutes (see /tmp/pf-emulator.log; a damaged AVD: Wipe Data in" \
          "Android Studio's Device Manager)." >&2
        exit 1
      fi
      sleep 3
      ((waited += 3))
    done
  fi
  adb reverse "tcp:$METRO_PORT" "tcp:$METRO_PORT" >/dev/null
  echo "Android device ready, Metro's port $METRO_PORT forwarded."
}

# Boots the iOS simulator named $1 (ipad: the first iPad Pro 13-inch) and sets SIM_UDID. Without a name an already
# booted simulator is reused, otherwise the first available iPhone is booted; a named one is booted even if another
# simulator runs.
SIM_UDID=""
boot_simulator() {
  local name="${1:-}" line
  if [[ -z "$name" ]]; then
    SIM_UDID="$(xcrun simctl list devices booted 2>/dev/null | grep -m1 -oE '[0-9A-F]{8}-([0-9A-F]{4}-){3}[0-9A-F]{12}' || true)"
    if [[ -n "$SIM_UDID" ]]; then
      open_simulator_app
      return 0
    fi
    line="$(xcrun simctl list devices available | grep -m1 "    iPhone" || true)"
  elif [[ "$name" == ipad ]]; then
    line="$(xcrun simctl list devices available | grep -m1 "    iPad Pro 13-inch" || true)"
  else
    line="$(xcrun simctl list devices available | grep -F -m1 "    $name (" || true)"
  fi
  SIM_UDID="$(grep -oE '[0-9A-F]{8}-([0-9A-F]{4}-){3}[0-9A-F]{12}' <<<"$line" || true)"
  if [[ -z "$SIM_UDID" ]]; then
    echo "No iOS simulator ${name:+named '$name' }available: install a runtime (xcodebuild -downloadPlatform iOS)." >&2
    exit 1
  fi
  if grep -q "(Booted)" <<<"$line"; then
    :
  else
    echo "Booting simulator: $(sed -E 's/^ +//; s/ \(.*//' <<<"$line")"
    xcrun simctl boot "$SIM_UDID"
  fi
  open_simulator_app
}

# Warns if no server answers on the slot's port.
check_server() {
  if ! curl -fsS -o /dev/null --max-time 3 "http://localhost:$SPRING_PORT/rsPublic/systemStatus"; then
    local start="bin/pfDev.sh run"
    ((SLOT == 0)) || start+=" $SLOT"
    echo "Warning: no server answers on :$SPRING_PORT (start it with: $start)." >&2
  fi
}

# Starts the fake SSO proxy in the background (stopped with this script), unless one runs on its port already.
start_proxy() {
  if lsof -nP -iTCP:"$PROXY_PORT" -sTCP:LISTEN >/dev/null 2>&1; then
    echo "Fake SSO proxy already running on :$PROXY_PORT."
    return 0
  fi
  node "$APP/tools/fake-sso-proxy.mjs" --upstream "http://localhost:$SPRING_PORT" --port "$PROXY_PORT" \
    --login-port "$SSO_PORT" &
  local pid=$!
  trap 'kill '"$pid"' 2>/dev/null || true' EXIT
}

cmd_proxy() {
  check_server
  cd "$APP" && exec node tools/fake-sso-proxy.mjs --upstream "http://localhost:$SPRING_PORT" --port "$PROXY_PORT" \
    --login-port "$SSO_PORT" "$@"
}

cmd_run() {
  local host=localhost android="" proxy="" device_given="" sim_name="" args=()
  for arg in "$@"; do
    case "$arg" in
      --android) android=yes; host=10.0.2.2 ;;
      --ipad) sim_name=ipad ;;
      --proxy) proxy=yes ;;
      -d | --device | -d=* | --device=*) device_given=yes; args+=("$arg") ;;
      *) args+=("$arg") ;;
    esac
  done
  check_server
  local server="http://$host:$SPRING_PORT"
  if [[ -n "$proxy" ]]; then
    if [[ -n "$android" ]]; then
      # The SSO login on 127.0.0.1 would be the emulator itself, not the Mac.
      echo "--proxy works on iOS only (the SSO login of the fake proxy is on the Mac's loopback)." >&2
      exit 1
    fi
    start_proxy
    server="http://localhost:$PROXY_PORT"
  fi
  ensure_deps
  cd "$APP"
  export EXPO_PUBLIC_PF_SERVER="$server"
  echo "Server preset in the login: $server, Metro on :$METRO_PORT"
  if [[ -n "$android" ]]; then
    boot_emulator
    # The app reaches Metro on localhost: the port is forwarded by adb reverse.
    REACT_NATIVE_PACKAGER_HOSTNAME=localhost npx expo run:android --port "$METRO_PORT" ${args[@]+"${args[@]}"}
    return
  fi
  if [[ -z "$device_given" && "$(uname)" == Darwin ]]; then
    # The simulator reaches Metro on localhost: the LAN address expo announces may be a VPN's or drop.
    export REACT_NATIVE_PACKAGER_HOSTNAME=localhost
    boot_simulator "$sim_name"
    # Explicitly: an iPhone in reach (wireless debugging) is an iOS device as well, expo would ask which one.
    args=(--device "$SIM_UDID" ${args[@]+"${args[@]}"})
  fi
  # Not exec: the trap of start_proxy stops the proxy with Metro.
  npx expo run:ios --port "$METRO_PORT" ${args[@]+"${args[@]}"}
}

cmd_metro() {
  local server="http://localhost:$SPRING_PORT" android=""
  check_server
  for arg in "$@"; do
    case "$arg" in
      --proxy)
        start_proxy
        server="http://localhost:$PROXY_PORT"
        ;;
      --android) android=yes ;;
    esac
  done
  ensure_deps
  cd "$APP"
  local start_args=()
  if [[ -n "$android" ]]; then
    boot_emulator
    server="http://10.0.2.2:$SPRING_PORT"
    start_args=(--android)
  fi
  echo "Server preset in the login: $server, Metro on :$METRO_PORT"
  REACT_NATIVE_PACKAGER_HOSTNAME="${REACT_NATIVE_PACKAGER_HOSTNAME:-localhost}" EXPO_PUBLIC_PF_SERVER="$server" \
    npx expo start --dev-client --port "$METRO_PORT" ${start_args[@]+"${start_args[@]}"}
}

cmd="${1:-help}"
shift || true
parse_slot "${1:-}"
((SLOT == 0)) || shift

case "$cmd" in
  help | -h | --help)
    usage
    exit 0
    ;;
  sim)
    boot_simulator "${1:-}"
    exit 0
    ;;
  emulator)
    boot_emulator "${1:-}"
    exit 0
    ;;
  xcode)
    exec open "$(ls -d "$APP"/ios/*.xcworkspace 2>/dev/null | head -1)"
    ;;
  proxy)
    cmd_proxy "$@"
    ;;
esac

command -v npx >/dev/null 2>&1 || { echo "Node/npm not found: brew install node" >&2; exit 1; }
cd "$APP"
case "$cmd" in
  run)
    cmd_run "$@"
    ;;
  metro)
    cmd_metro "$@"
    ;;
  devices)
    xcrun simctl list devices available 2>/dev/null || true
    echo
    if command -v adb >/dev/null 2>&1; then adb devices -l; else echo "adb not found (Android SDK: Android Studio's setup)"; fi
    ;;
  check)
    ensure_deps
    npx tsc --noEmit
    npx tsc -p "$ROOT/projectforge-shared/tsconfig.json"
    npx eslint .
    exec npx jest
    ;;
  test)
    ensure_deps
    exec npx jest "$@"
    ;;
  lint)
    exec npx eslint .
    ;;
  format)
    exec npx eslint --fix .
    ;;
  typecheck)
    exec npx tsc --noEmit
    ;;
  prebuild)
    ensure_deps
    exec npx expo prebuild --clean ${1:+--platform "$1"}
    ;;
  build-ios)
    ensure_deps
    if [[ "${1:-}" == --release ]]; then
      APP_VARIANT=production exec npx expo run:ios --configuration Release --no-bundler "${@:2}"
    fi
    exec npx expo run:ios --no-bundler "$@"
    ;;
  build-android)
    ensure_deps
    if [[ "${1:-}" == --release ]]; then
      APP_VARIANT=production exec npx expo run:android --variant release --no-bundler "${@:2}"
    fi
    exec npx expo run:android --no-bundler "$@"
    ;;
  clean)
    rm -rf ios android .expo node_modules
    npm install
    exec npx expo prebuild --clean --no-install
    ;;
  deps)
    npm install
    exec npx expo install --check
    ;;
  doctor)
    exec npx expo-doctor
    ;;
  eas)
    ensure_deps
    # The Expo account and project aren't in the repository (app.config.ts).
    if [[ -f "$APP/.env.local" ]]; then
      set -a
      # shellcheck disable=SC1091
      source "$APP/.env.local"
      set +a
    fi
    # A submit profile has no env: without this it would look up the dev app de.projectforge.mobileapp.dev.
    export APP_VARIANT="${APP_VARIANT_GIVEN:-production}"
    cd "$APP" && exec npx --yes eas-cli@latest "$@"
    ;;
  logs)
    exec xcrun simctl spawn booted log stream --level debug --predicate 'process == "ProjectForgeRN"'
    ;;
  *)
    echo "Unknown command: $cmd" >&2
    usage >&2
    exit 1
    ;;
esac
